import { Injectable, Injector } from '@angular/core';
import { SuperService } from './super.service';
import { Ciudad } from '../models/ciudad.model';

@Injectable({
    providedIn: 'any'
})
export class CiudadService extends SuperService<Ciudad> {
    protected override model: string = "ciudades";
    protected override columns: (keyof Ciudad)[]=[
        'nombre',
        'tipo',
        'estado_id',
    ];

    constructor(injector: Injector) {
        super(injector)
    }
}