import { Component } from '@angular/core';
import { Ciudad } from '../../../models/ciudad.model';
import { CiudadService } from '../../../controllers/ciudad.service';
import { Form, GenericFormComponent } from "../../../shared/generic-form/generic-form.component";
import { ActivatedRoute } from '@angular/router';

const FORM:Form=[
  {
    key:'nombre',
    label:'Nombre',
    type:'text',
    validator:{
      required:true,
    }
  },
  {
    key:'tipo',
    label:'Tipo de Ciudad',
    defaultOption:'CIUDAD',
    options:['CIUDAD','MUNICIPIO','POBLACION'],
  },
  {
    apiUrl:'api/estados',
    key:'estado_id',
    label:'Estado',
    keyList:'id',
    keyDetalle:'nombre',
    validator:{
      required:true,
    }
  }
]

@Component({
  selector: 'app-form-ciudades',
  imports: [GenericFormComponent],
  templateUrl: './form-ciudades.component.html',
  styleUrl: './form-ciudades.component.css'
})
export class FormCiudadesComponent {
  edit?:Ciudad
  form= FORM

  constructor(
    public ciudadController: CiudadService,
    private route: ActivatedRoute,
  ){}

  ngOnInit(){
    this.route.params.subscribe(async params =>{
      const id = params['ciudad_id']
      if(id){
        this.edit= await this.ciudadController.find(id)
      }
    })
  }
}
